recipes.code:
{
  "inputs": [
    {
      "id": "sendinel-api-key",
      "type": "promptString",
      "description": "Sendinel API key. Required for stdio startup and scopes the server to a project.",
      "password": true
    }
  ],
  "servers": {
    "server": {
      "type": "stdio",
      "command": "npx",
      "args": [
        "-y",
        "@sendinel/mcp-server@1.0.7"
      ],
      "env": {
        "SENDINEL_API_KEY": "${input:sendinel-api-key}"
      }
    }
  }
}
